import{_ as p,a0 as l,w as a,s as d,I as o,x as s,a1 as r,A as i,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 中像專業人士一樣使用 GNOME 截圖工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中像專業人士一樣使用 GNOME 截圖工具 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中像專業人士一樣使用 GNOME 截圖工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中像專業人士一樣使用 GNOME 截圖工具 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro","title":"在 Linux 中像專業人士一樣使用 GNOME 截圖工具","tag":"202201","desc":""},"relativePath":"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro.md","filePath":"[post].md"}'),m={name:"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro.md"};function f(u,t,h,g,S,x){const e=l("Link");return a(),d("div",null,[t[26]||(t[26]=o("h1",{id:"在-linux-中像專業人士一樣使用-gnome-截圖工具",tabindex:"-1"},[s("在 Linux 中像專業人士一樣使用 GNOME 截圖工具 "),o("a",{class:"header-anchor",href:"#在-linux-中像專業人士一樣使用-gnome-截圖工具","aria-label":"Permalink to “在 Linux 中像專業人士一樣使用 GNOME 截圖工具”"},"​")],-1)),o("p",null,[t[2]||(t[2]=s("有 ",-1)),r(e,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...t[0]||(t[0]=[s("幾個可用於 Linux 的截圖工具",-1)])]),_:1}),t[3]||(t[3]=s("，我喜歡 ",-1)),r(e,{href:"https://itsfoss.com/flameshot/"},{default:i(()=>[...t[1]||(t[1]=[s("使用 Flameshot 進行截圖",-1)])]),_:1}),t[4]||(t[4]=s(" 和 Shutter 來編輯現有的截圖。",-1))]),t[27]||(t[27]=o("p",null,"但不幸的是，Flameshot 不能在 4K 屏幕上工作。因此，我不得不使用默認的 GNOME 截圖工具，它在我的帶有超高清屏幕的戴爾 XPS 上工作得非常好。",-1)),t[28]||(t[28]=o("p",null,[o("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-screenshot-tool.jpg?resize=800%2C413&ssl=1",alt:"GNOME screenshot tool"})],-1)),o("p",null,[t[6]||(t[6]=s("這一“被迫之舉”讓我意識到，如果你知道如何正確使用，",-1)),r(e,{href:"https://apps.gnome.org/app/org.gnome.Screenshot/"},{default:i(()=>[...t[5]||(t[5]=[s("GNOME 截圖",-1)])]),_:1}),t[7]||(t[7]=s(" 並不是一個糟糕的工具。",-1))]),t[29]||(t[29]=n('<p>在這裏，我指的是用鍵盤快捷鍵來使用它，因為這樣可以節省大量的時間。</p><p>讓我展示一下如何像專家一樣用那些方便的鍵盤快捷鍵來使用 GNOME 截圖應用。</p><p>我假定你沒有改變這裏的默認的截圖的鍵盤快捷鍵。</p><h3 id="對整個屏幕進行截圖-使用-prt-scr-鍵" tabindex="-1">對整個屏幕進行截圖：使用 Prt Scr 鍵 <a class="header-anchor" href="#對整個屏幕進行截圖-使用-prt-scr-鍵" aria-label="Permalink to “對整個屏幕進行截圖：使用 Prt Scr 鍵”">​</a></h3><p>這是最簡單的操作。在你的鍵盤上找到 <code>Prt Sc</code>（或稱 <code>Prt Scr</code>、<code>Prt Scn</code>）鍵並按下它。它將對整個屏幕進行截圖，並將其保存在你的主目錄下的圖片文件夾中。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/screenshot-of-entire-screen-gnome.jpg?resize=800%2C532&amp;ssl=1" alt="Screenshot of entire screen saved as PNG file"></p><p>在某些發行版（或版本）中，你可能會看到是否要保存截圖的選項，但大多數情況下，它會自動保存屏幕截圖。</p><p>這裏需要注意的另一件事是，如果你有多個屏幕連接到系統上，它會把所有的屏幕一起截圖。這意味着，你會得到一個超寬的圖像。</p><p>但是，如果你只想對某個應用進行截圖，而不是對整個屏幕進行截圖呢？</p><h3 id="給一個應用程序的窗口截圖-使用-alt-prt-scr-鍵" tabindex="-1">給一個應用程序的窗口截圖：使用 Alt+Prt Scr 鍵 <a class="header-anchor" href="#給一個應用程序的窗口截圖-使用-alt-prt-scr-鍵" aria-label="Permalink to “給一個應用程序的窗口截圖：使用 Alt+Prt Scr 鍵”">​</a></h3><p>要給正在運行的圖形應用截圖，你需要這樣做：</p><p>點擊正在運行的應用，使其獲得焦點。現在，按住 <code>Alt</code> 鍵並按 <code>Prt Scr</code> 鍵。</p><p>它將得到應用窗口的截圖，並保存到圖片目錄中。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/screenshot-of-an-application-windows-gnome.png?resize=800%2C437&amp;ssl=1" alt="Screenshot of an application window in GNOME"></p><p>這樣獲取的截圖也有一個陰影效果，看起來很不錯。</p><p>這很好，但如果你只想給某個特定區域截圖，而不是整個屏幕呢？這也有一個技巧。</p><h3 id="對屏幕的選定區域進行截圖-使用-shift-prt-scr-鍵" tabindex="-1">對屏幕的選定區域進行截圖：使用 Shift+Prt Scr 鍵 <a class="header-anchor" href="#對屏幕的選定區域進行截圖-使用-shift-prt-scr-鍵" aria-label="Permalink to “對屏幕的選定區域進行截圖：使用 Shift+Prt Scr 鍵”">​</a></h3><p>按住 <code>Shift</code> 鍵。然後按 <code>Prt Scr</code> 鍵。你會看到屏幕上出現一個選框。將鼠標移動到所需的區域，開始拖動光標。它將高亮顯示該區域，並在你釋放鼠標後立即進行截圖。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/take-screenshot-of-region-gnome.webp?resize=800%2C430&amp;ssl=1" alt="Taking screenshot of an area in GNOME"></p><h3 id="複製截圖到剪貼板而不是保存它們" tabindex="-1">複製截圖到剪貼板而不是保存它們 <a class="header-anchor" href="#複製截圖到剪貼板而不是保存它們" aria-label="Permalink to “複製截圖到剪貼板而不是保存它們”">​</a></h3><p>當你在和別人聊天時，要和對方分享屏幕截圖時，這非常有用。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/saving-screenshot-to-clipboard-and-using-it.webp?resize=800%2C476&amp;ssl=1" alt="Screenshot copied to the clipboard can be used in various applications"></p><p>首先截圖，但沒必要將保存的截圖文件附在聊天工具中。相反，你可以直接將截圖複製到剪貼板，然後使用 <code>Ctrl+V</code> 快捷鍵將圖像（從剪貼板）粘貼到聊天工具。</p><p>這樣，你的系統就不會保留不必要的截圖，你也可以節省一些鼠標點擊次數。</p><p>要把截圖保存到剪貼板，以便你能把它們粘貼到聊天工具、繪圖工具或文檔中，你必須把 <code>Ctrl</code> 鍵和你在前面幾節中看到的其他截圖快捷鍵一起使用。</p><ul><li><code>Ctrl+Prt Scr</code>：將整個屏幕的截圖複製到剪貼板上。</li><li><code>Ctrl+Alt+Prt Scr</code>：將應用窗口的截圖複製到剪貼板上。</li><li><code>Ctrl+Shift+Prt Scr</code>：將選定區域的截圖複製到剪貼板上</li></ul>',26)),o("p",null,[t[9]||(t[9]=s("我必須補充一點，在這種情況下，",-1)),r(e,{href:"https://itsfoss.com/flameshot/"},{default:i(()=>[...t[8]||(t[8]=[s("使用像 Flameshot 這樣的工具",-1)])]),_:1}),t[10]||(t[10]=s(" 甚至更好一些，因為它允許你在將截圖保存到剪貼板之前對其進行註釋。這樣，你可以很容易地高亮屏幕的重要部分。",-1))]),t[30]||(t[30]=n('<h3 id="在截圖中添加延遲-以便對下拉菜單進行截圖" tabindex="-1">在截圖中添加延遲，以便對下拉菜單進行截圖 <a class="header-anchor" href="#在截圖中添加延遲-以便對下拉菜單進行截圖" aria-label="Permalink to “在截圖中添加延遲，以便對下拉菜單進行截圖”">​</a></h3><p>到目前為止，一切都很好。你只需按下幾個鍵，就可以隨心所欲地進行截圖了。</p><p>問題是，當你要對下拉菜單或右鍵動作等進行截圖時。當你按下屏幕截圖鍵時，想要的項目可能會消失。</p><p>為了處理這種情況，你可以對該區域或整個屏幕進行截圖，但要有一個延遲。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/taking-screenshot-with-delay-gnome.webp?resize=800%2C428&amp;ssl=1" alt="Taking screenshot with delay"></p><p>在 GNOME 屏幕截圖工具中，你可以選擇添加這個延遲。例如，你添加了 6 秒的延遲。你點擊截圖按鈕，有 6 秒時間來做/顯示你想做的事情。6 秒後，它就會自動截圖了。</p><h3 id="你有什麼技巧嗎" tabindex="-1">你有什麼技巧嗎？ <a class="header-anchor" href="#你有什麼技巧嗎" aria-label="Permalink to “你有什麼技巧嗎？”">​</a></h3><p>這就是我使用 GNOME 截圖工具的所有技巧。如果你還沒有廣泛地使用它，你應該會發現它很有幫助。如果你已經是一個專家，也許你知道一些可以添加到本文中的東西？請在評論區與我們其他人分享吧。</p><hr>',9)),o("p",null,[t[12]||(t[12]=s("via: ",-1)),r(e,{href:"https://itsfoss.com/using-gnome-screenshot-tool/"},{default:i(()=>[...t[11]||(t[11]=[s("https://itsfoss.com/using-gnome-screenshot-tool/",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=s("作者：",-1)),r(e,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...t[13]||(t[13]=[s("Abhishek Prakash",-1)])]),_:1}),t[18]||(t[18]=s(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[14]||(t[14]=[s("lujun9972",-1)])]),_:1}),t[19]||(t[19]=s(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...t[15]||(t[15]=[s("geekpi",-1)])]),_:1}),t[20]||(t[20]=s(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[16]||(t[16]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=s("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[21]||(t[21]=[s("LCTT",-1)])]),_:1}),t[24]||(t[24]=s(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...t[22]||(t[22]=[s("Linux中國",-1)])]),_:1}),t[25]||(t[25]=s(" 榮譽推出",-1))])])}const N=p(m,[["render",f]]);export{C as __pageData,N as default};
